# Own-wording subclasses of Artificer Expansion Pack (2024) and Specialist Upgrades for the Artificer subclasses of the app.
# SUB = four new subclasses. EXT = upgrade picks added to existing subclasses while the book is on.

def _p(l, key, feature, title, lst):
    return {"l": l, "k": "opts", "n": 1, "key": key, "feature": feature, "title": title, "list": [list(x) for x in lst]}

