OFA = [
 ("Problem Solver", "When you use Tinker's Magic you can make a problem solving tool instead of normal equipment. It is a Tiny object that appears in an open space within 5 ft. When you create it, name a specific ability check, with its ability score, its skill if any, and its goal. A creature carrying the tool has Advantage on a check that fits your description, and then the tool vanishes. If unused it lasts until you finish a Long Rest. Example: Advantage on a Strength (Athletics) check to swim in rough water, or on an Intelligence (Investigation) check to find a piece of lore in a library.", None, 1),
 ("Upgraded Weapons", "When you make a magic weapon with Replicate Magic Item, you can augment the special weapon of your Armor Model instead. It gains the magic item's properties if the special weapon is an eligible type. It can bear one augmentation at a time. If the magic item would be destroyed, the weapon returns to normal. If you switch Armor Model and the new weapon is not eligible, it cannot use the properties. Otherwise they carry over. While augmented this way you cannot use the Improved Arsenal benefit of Improved Armorer from level 9.", "Armorer", 5),
 ("Alchemical Grenades", "**Free Cantrip.** You learn Acid Splash, Fire Bolt, or Poison Spray, and it does not count against your cantrips known. **Creating a Grenade.** When you start casting a spell with Alchemist's Supplies as the focus, you can make it an Alchemical Grenade. The spell must deal Acid, Fire, Necrotic, or Poison damage. You can ignore its Verbal components. **Alchemical Explosion.** If the spell targets only one creature, each other creature within 5 ft of the target makes a Dexterity save against your spell save DC. On a fail it takes damage of the spell's type equal to half your Artificer level (round up). A spell that already targets an area does not gain this. The radius is 10 ft from level 9. **Alchemical Savant.** The extra damage from Alchemical Savant applies only to the spell's target, not to the Alchemical Explosion, since that damage is separate.", "Alchemist", 3),
]
OLD = ["Alchemist", "Armorer", "Artillerist", "Battle Smith", "Cartographer"]
NEW = ["Forceforger", "Magneticist", "Mutagenist", "Portalweaver"]

def _ups(sub):
    return [(n, t, l) for n, t, s, l in UP if s == sub]

def _picks(sub, ofa_lvl):
    out = []
    ups = _ups(sub)
    for tier in (3, 6, 17):
        lst = [[n, t] for n, t, l in ups if l <= tier]
        out.append(_p(tier, "tsae_su%d" % tier, "Specialist Upgrade", "Specialist Upgrade (level %d)" % tier, lst))
    lst = [[n, t] for n, t, s, l in OFA if (s is None or s == sub)]
    out.append(_p(ofa_lvl, "tsae_ofa", "Optional Feature", "Optional Artificer feature", lst))
    return out

EXT = []
for _s in OLD:
    EXT.append({"cls": "Artificer", "sub": _s, "pick": _picks(_s, 5 if _s == "Armorer" else 3)})

